import {measureLoudness} from './loudness.js';
const db=v=>10**(v/20);
export class ExperienceMixer {
 constructor(){this.context=null;this.cache=new Map();this.pending=new Map();this.active=[];this.volume=.65;this.muted=false;this.starts=[];this.voiceTrim=1;}
 async start(){if(!this.context){const c=this.context=new AudioContext({sampleRate:48000});this.master=c.createGain();this.master.gain.value=this.volume;this.limiter=c.createDynamicsCompressor();this.limiter.threshold.value=-8;this.limiter.knee.value=8;this.limiter.ratio.value=8;this.master.connect(this.limiter);this.analyser=c.createAnalyser();this.analyser.fftSize=2048;this.limiter.connect(this.analyser);this.analyser.connect(c.destination);this.capture=c.createMediaStreamDestination();this.analyser.connect(this.capture);this.buses={};for(const name of ['music','atmo','voice']){const bus=c.createGain();bus.gain.value=name==='voice'?.7:1;bus.connect(this.master);this.buses[name]=bus;}this.meter=new Float32Array(2048);}await this.context.resume();}
 async buffer(file){if(this.cache.has(file))return this.cache.get(file);const response=await fetch('./private/'+file);if(!response.ok)throw Error('Audio unavailable: '+file);const buffer=await this.context.decodeAudioData(await response.arrayBuffer());const meter=measureLoudness(Array.from({length:buffer.numberOfChannels},(_,i)=>buffer.getChannelData(i)),buffer.sampleRate);buffer.kfbMeter=meter;this.cache.set(file,buffer);return buffer;}
 async prepare(recipe){await Promise.all([...recipe.music,...recipe.atmo].map(f=>this.buffer(f)));}
 async change(recipe){await this.prepare(recipe);const c=this.context,now=c.currentTime,old=this.active,lanes={},nodes=[];
 for(const [bus,files] of [['music',recipe.music],['atmo',recipe.atmo]]){const fade=c.createGain();fade.gain.setValueAtTime(0,now);fade.gain.linearRampToValueAtTime(1,now+.48);fade.connect(this.buses[bus]);lanes[bus]=fade;
 for(const [i,file] of files.entries()){const src=c.createBufferSource();src.buffer=this.cache.get(file);src.loop=true;const level=c.createGain();const norm=Math.min(12,db(-13.5-src.buffer.kfbMeter.integratedLufs));level.gain.value=norm*db(recipe.mixDb[bus][i])/(bus==='music'?Math.sqrt(files.length):1);src.connect(level);level.connect(fade);src.start(now);nodes.push(src);}}
 this.active=[{lanes,nodes,room:recipe.id}];this.starts.push({room:recipe.id,at:now});this.voiceTrim=recipe.mixDb.voice===null?0:db(recipe.mixDb.voice);if(this.voiceLevel)this.voiceLevel.gain.setTargetAtTime((this.voiceBase||1)*this.voiceTrim,now,.04);
 for(const g of old){for(const lane of Object.values(g.lanes)){lane.gain.cancelScheduledValues(now);lane.gain.setValueAtTime(lane.gain.value,now);lane.gain.linearRampToValueAtTime(0,now+.48);setTimeout(()=>lane.disconnect(),600);}for(const n of g.nodes)n.stop(now+.5);}
 // Retain only current and next room buffers.
 const keep=new Set([...recipe.music,...recipe.atmo]);const next=this.recipes?.[(this.recipes.indexOf(recipe)+1)%3];if(next)for(const f of [...next.music,...next.atmo])keep.add(f);for(const key of this.cache.keys())if(!keep.has(key))this.cache.delete(key);
 }
 attachVideo(video){const c=this.context;this.videoSource=c.createMediaElementSource(video);this.voiceLevel=c.createGain();this.voiceBase=1;this.panner=c.createPanner();this.panner.panningModel='HRTF';this.panner.distanceModel='inverse';this.panner.refDistance=3;this.panner.rolloffFactor=.2;this.panner.positionX.value=-3.6;this.panner.positionY.value=.6;this.panner.positionZ.value=-6;this.voiceAnalyser=c.createAnalyser();this.voiceAnalyser.fftSize=1024;this.voiceSamples=new Float32Array(1024);this.videoSource.connect(this.voiceLevel);this.voiceLevel.connect(this.panner);this.panner.connect(this.voiceAnalyser);this.voiceAnalyser.connect(this.buses.voice);}
 async voiceClip(file){const b=await this.buffer(file);this.voiceBase=Math.min(12,db(-10.5-b.kfbMeter.integratedLufs));this.voiceLevel.gain.setTargetAtTime(this.voiceBase*this.voiceTrim,this.context.currentTime,.04);this.cache.delete(file);}
 duck(on){if(!this.context||this.ducked===on)return;this.ducked=on;this.buses.music.gain.setTargetAtTime(on?db(-8):1,this.context.currentTime,on?.08:.4);}
 updateVoice(){if(!this.voiceAnalyser)return;this.voiceAnalyser.getFloatTimeDomainData(this.voiceSamples);let sum=0;for(const v of this.voiceSamples)sum+=v*v;this.duck(Math.sqrt(sum/this.voiceSamples.length)>.008);}
 setVolume(value){this.volume=value;if(this.context)this.master.gain.setTargetAtTime(this.muted?0:value,this.context.currentTime,.04);}
 toggleMute(){this.muted=!this.muted;this.setVolume(this.volume);return this.muted;}
 headphones(on){const c=this.context;if(!c)return;if(on&&!this.binaural){const gain=c.createGain();gain.gain.value=.008;gain.connect(this.buses.atmo);const nodes=[];for(const [hz,pan] of [[180,-1],[186,1]]){const osc=c.createOscillator(),p=c.createStereoPanner();osc.frequency.value=hz;p.pan.value=pan;osc.connect(p);p.connect(gain);osc.start();nodes.push(osc);}this.binaural={gain,nodes};}else if(!on&&this.binaural){for(const n of this.binaural.nodes)n.stop();this.binaural.gain.disconnect();this.binaural=null;}}
 level(){if(!this.analyser)return {rmsDb:null,peakDb:null};this.analyser.getFloatTimeDomainData(this.meter);let sum=0,peak=0;for(const v of this.meter){sum+=v*v;peak=Math.max(peak,Math.abs(v));}return {rmsDb:20*Math.log10(Math.max(1e-8,Math.sqrt(sum/this.meter.length))),peakDb:20*Math.log10(Math.max(1e-8,peak))};}
 dispose(){this.context?.close();}
}
